<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address'])]; if($id){$pdo->prepare("UPDATE customers SET name=?,phone=?,email=?,address=? WHERE id=?")->execute([...$d,$id]);flash('success','Customer updated.');}else{$pdo->prepare("INSERT INTO customers(name,phone,email,address) VALUES(?,?,?,?)")->execute($d);flash('success','Customer added.');}header("Location:index.php");exit;}
if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM customers WHERE id=?")->execute([(int)$_GET['delete']]);flash('success','Customer deleted.');header("Location:index.php");exit;}
$q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT * FROM customers WHERE name LIKE ? OR phone LIKE ? OR email LIKE ? ORDER BY id DESC");$st->execute(["%$q%","%$q%","%$q%"]);$rows=$st->fetchAll();$page_title='Customers';require __DIR__.'/../partials/header.php';?>
<div class="d-flex justify-content-between mb-3"><div><h3 class="fw-bold">Customers</h3><p class="text-muted">Manage customer accounts.</p></div></div>
<div class="row g-3"><div class="col-lg-4"><div class="card p-3"><h6 class="fw-bold">Add Customer</h6><form method="post"><input class="form-control mb-2" name="name" required placeholder="Full name"><input class="form-control mb-2" name="phone" placeholder="Phone"><input class="form-control mb-2" type="email" name="email" placeholder="Email"><textarea class="form-control mb-2" name="address" placeholder="Address"></textarea><button class="btn btn-primary w-100">Save Customer</button></form></div></div>
<div class="col-lg-8"><div class="card p-3"><form class="d-flex gap-2 mb-3"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search customers"><button class="btn btn-outline-secondary">Search</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['email'])?></td><td class="text-end"><a class="btn btn-sm btn-outline-danger" onclick="return confirmDelete()" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require __DIR__.'/../partials/footer.php';?>
